from __future__ import annotations

import json
from pathlib import Path


ROOT = Path(__file__).resolve().parent
GRAPH = ROOT / "rd_grafo_relaciones_2026-08-11.json"
REGISTRY = ROOT / "rd_universo_entidades_2026-08-11.json"
SOURCES = ROOT / "rd_fuentes_catalogo_2026-08-11.json"
OUTPUT = ROOT / "rd_matriz_interactiva_2026-08-11.html"


HTML = r'''<!doctype html>
<html lang="es">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Matriz relacional - Reduciendo Daño</title>
<style>
:root{--bg:#08090d;--panel:#11131a;--line:#2b2e3b;--text:#f0f1f5;--muted:#a8adbc;--acid:#dcff36;--cyan:#58e8f2;--orange:#ffad5c;--red:#ff5f6d;--violet:#b98cff;--green:#66e6a0}
*{box-sizing:border-box}html{background:var(--bg);color:var(--text)}body{margin:0;min-width:1050px;font:14px Inter,system-ui,sans-serif;background:radial-gradient(circle at 90% 0,#12313a55,transparent 34rem),var(--bg)}button,input,select{font:inherit}button{cursor:pointer}.shell{max-width:1700px;margin:auto;padding:28px 32px 60px}.eyebrow{color:var(--acid);letter-spacing:.25em;text-transform:uppercase;font-size:11px;font-weight:800}h1{font-size:clamp(36px,5vw,68px);line-height:.95;letter-spacing:-.06em;margin:12px 0}h1 span{color:var(--muted);font-weight:350}.intro{max-width:920px;color:var(--muted);font-size:16px;line-height:1.55}.contract{max-width:1100px;padding:16px 18px;margin:22px 0;border:1px solid #dcff3655;border-left:4px solid var(--acid);border-radius:12px;background:#dcff360d}.contract strong{color:var(--acid)}.contract p{margin:6px 0;line-height:1.5}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:22px 0}.stat,.panel{background:#11131aee;border:1px solid var(--line);border-radius:14px}.stat{padding:15px}.stat b{font-size:30px;display:block}.stat small,.panel-head small{color:var(--muted)}.controls{display:grid;grid-template-columns:2fr repeat(4,1fr);gap:9px;margin:18px 0}.control label{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.12em;margin-bottom:5px}.control input,.control select{width:100%;background:var(--panel);color:var(--text);border:1px solid var(--line);border-radius:8px;padding:10px}.tabs{display:flex;gap:8px;margin:12px 0}.tab{border:1px solid var(--line);background:none;color:var(--muted);border-radius:99px;padding:9px 14px}.tab.active{background:var(--acid);color:var(--bg);border-color:var(--acid);font-weight:800}.workspace{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(350px,.75fr);gap:14px;align-items:start}.panel{overflow:hidden}.panel-head{display:flex;justify-content:space-between;gap:12px;padding:16px 18px;border-bottom:1px solid var(--line)}.panel-head h2{font-size:17px;margin:0}.matrix-scroll{overflow:auto;max-height:750px;padding:12px}.matrix{display:grid;grid-template-columns:178px repeat(48,42px);grid-auto-rows:42px;width:max-content}.corner{background:var(--panel);border-bottom:1px solid var(--line);border-right:1px solid var(--line)}.axis{font-size:9px;color:var(--muted);overflow:hidden;white-space:nowrap}.axis.top{writing-mode:vertical-rl;transform:rotate(180deg);padding:5px 0;position:sticky;top:0;z-index:2;background:var(--panel);border-bottom:1px solid var(--line)}.axis.side{display:flex;align-items:center;padding:0 10px;position:sticky;left:0;z-index:1;background:var(--panel);border-right:1px solid var(--line)}.cell{display:grid;place-items:center;border-bottom:1px solid #2b2e3b99;border-right:1px solid #2b2e3b99}.cell button{width:24px;height:24px;border:0;border-radius:50%;font-size:10px;font-weight:900;color:var(--bg)}.cell button:hover{outline:2px solid white;transform:scale(1.15)}.cell.empty{color:#454958}.dot-comparison{background:var(--cyan)}.dot-interaction{background:var(--orange)}.dot-adulterant_of{background:var(--red)}.dot-presumptive_presence_signal_for{background:var(--acid)}.dot-test_limit_of{background:var(--violet)}.dot-derivative_of{background:var(--green)}.dot-medication_interaction{background:#ff78c8}.dot-contextual_relation{background:#9d9da8}.legend{display:flex;flex-wrap:wrap;gap:8px 14px;padding:0 18px 15px;color:var(--muted);font-size:11px}.legend i{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px}.detail{min-height:340px}.detail-body{padding:19px}.empty{color:var(--muted);line-height:1.6}.kicker{color:var(--acid);font-size:10px;text-transform:uppercase;letter-spacing:.15em;font-weight:800}.detail h3{font-size:26px;letter-spacing:-.04em;margin:8px 0 12px}.pill{display:inline-block;border:1px solid var(--line);border-radius:99px;padding:5px 8px;color:var(--cyan);font-size:11px}.detail dl{display:grid;grid-template-columns:110px 1fr;gap:8px;margin:18px 0;font-size:13px}.detail dt{color:var(--muted)}.detail dd{margin:0}.note{border-left:3px solid var(--orange);background:#ffad5c12;padding:10px 12px;line-height:1.5}.sources{padding-left:18px;font-size:11px;line-height:1.6}.sources a{color:var(--cyan)}.relation-list{display:grid;gap:8px;padding:12px;max-height:620px;overflow:auto}.relation-card{text-align:left;color:var(--text);background:#171a23;border:1px solid var(--line);border-radius:10px;padding:11px}.relation-card:hover,.relation-card.selected{border-color:var(--cyan)}.relation-card .row{display:flex;justify-content:space-between;gap:8px}.relation-card strong{font-size:13px}.relation-card small{display:block;color:var(--muted);margin-top:5px}.badge{color:var(--acid);font-size:10px;text-transform:uppercase;white-space:nowrap}.coverage{margin-top:14px;padding:17px 18px}.coverage h2{font-size:17px;margin:0 0 7px}.coverage p{color:var(--muted);line-height:1.5}.unconnected{display:flex;flex-wrap:wrap;gap:6px}.unconnected span{font-size:11px;border:1px dashed #454958;border-radius:99px;padding:6px 8px;color:#c4c7d0}.footer{color:#777c8b;font-size:11px;line-height:1.5;margin-top:22px}@media(max-width:1200px){.workspace{grid-template-columns:1fr}.detail{min-height:0}}
</style></head>
<body><main class="shell">
<div class="eyebrow">Reduciendo Daño · grafo relacional · vista generada</div>
<h1>Matriz de relaciones <span>no de identidades</span></h1>
<p class="intro">Esta vista lee el registro universal y el grafo relacional. Una celda no decide qué es una muestra: muestra una relación documentada, su evidencia y sus límites.</p>
<section class="contract"><strong>Contrato de evidencia</strong><p>Un test puede producir una señal compatible con presencia presumible. No determina cantidad, pureza, potencia, seguridad ni composición completa. “Puede contener” no significa “es”.</p></section>
<section class="stats" id="stats"></section>
<section class="controls"><div class="control"><label>Buscar entidad o relación</label><input id="search" type="search" placeholder="MDMA, tusi, adulterante, test..." autocomplete="off"></div><div class="control"><label>Tipo</label><select id="relation"><option value="all">Todos</option></select></div><div class="control"><label>Estado</label><select id="status"><option value="all">Todos</option></select></div><div class="control"><label>Matriz</label><select id="matrix"><option value="all">Todas</option></select></div><div class="control"><label>Cobertura</label><select id="coverage"><option value="all">Todas</option><option value="connected">Conectadas</option><option value="unconnected">Sin relación en esta tanda</option></select></div></section>
<div class="tabs"><button class="tab active" data-tab="matrix-view">Matriz 48 × 48</button><button class="tab" data-tab="relations-view">Relaciones y evidencia</button></div>
<section class="workspace" id="matrix-view"><section class="panel"><div class="panel-head"><h2>Relaciones entre entidades</h2><small id="matrix-count"></small></div><div class="matrix-scroll"><div class="matrix" id="grid"></div></div><div class="legend" id="legend"></div></section><aside class="panel detail" id="detail"><div class="detail-body empty">Selecciona una celda o relación para leer su fuente, alcance y redacción permitida.</div></aside></section>
<section class="workspace" id="relations-view" hidden><section class="panel"><div class="panel-head"><h2>Relaciones y evidencia</h2><small id="relation-count"></small></div><div class="relation-list" id="list"></div></section><aside class="panel detail" id="detail2"><div class="detail-body empty">Selecciona una relación.</div></aside></section>
<section class="panel coverage"><h2>Entidades sin relación en esta tanda</h2><p>No se eliminan ni se conectan por similitud de nombres. Quedan en el universo y esperan una fuente específica o un estado revisado.</p><div class="unconnected" id="unconnected"></div></section>
<p class="footer">Fuente: <code>rd_universo_entidades_2026-08-11.json</code> + <code>rd_grafo_relaciones_2026-08-11.json</code>. Generado por <code>rd_matriz_interactiva_build.py</code>. La matriz es una vista, no la fuente de verdad.</p>
</main><script>
const data=__DATA__,records=data.registry.records,relations=data.graph.relations,contract=data.graph.evidence_contract,map=new Map(records.map(x=>[x.id,x]));
const labels={comparison:'comparación',interaction:'interacción',adulterant_of:'posible adulterante/contaminante de',presumptive_presence_signal_for:'señal de presencia presumible',test_limit_of:'límite de prueba para',derivative_of:'familia o derivado de',medication_interaction:'interacción con medicamento',contextual_relation:'relación contextual'};
const statuses={supported_candidate:'candidato respaldado',supported_with_scope_limit:'respaldado con límite',conflicting_candidate:'candidato con conflicto',insufficient_evidence:'evidencia insuficiente',context_only:'sólo contexto'};
const matrices={existing_matrix:'en matriz actual',matrix_candidate:'candidato a matriz',outside_initial_matrix:'fuera de matriz inicial'};
const state={search:'',relation:'all',status:'all',matrix:'all',coverage:'all'};
function label(ref){if(ref.startsWith('reagent:'))return ref.slice(8).replaceAll('_',' ');if(ref.startsWith('method:'))return 'método '+ref.slice(7).replaceAll('_',' ');if(ref.startsWith('specific_strip:'))return 'tira '+ref.slice(15).replaceAll('_',' ');return map.get(ref)?.display_name||ref}
function connected(id){return relations.some(r=>r.source_ref===id||r.target_ref===id)}
function searchable(r){return !state.search||[r.id,r.source_ref,r.target_ref,r.notes,label(r.source_ref),label(r.target_ref)].join(' ').toLowerCase().includes(state.search)}
function visibleRelations(){return relations.filter(r=>searchable(r)&&(state.relation==='all'||r.relation_type===state.relation)&&(state.status==='all'||r.status===state.status)&&(state.matrix==='all'||r.matrix_relevance===state.matrix))}
function entityVisible(id){const x=map.get(id),text=[id,x?.display_name||'',x?.aliases||''].join(' ').toLowerCase();return (!state.search||text.includes(state.search))&&(state.coverage==='all'||state.coverage==='connected'&&connected(id)||state.coverage==='unconnected'&&!connected(id))}
function links(r){return(r.evidence_urls||[]).map(u=>{const source=data.sources.records.find(x=>x.url===u);const type=source?.source_type||'unclassified';return `<li><span class="badge">${type}</span> <a href="${u}" target="_blank" rel="noreferrer">${u}</a></li>`}).join('')}
function detail(r){const signal=r.relation_type==='presumptive_presence_signal_for',target=label(r.target_ref),safe=signal?contract.allowed_public_templates[0].replace('{target}',target):'La relación no es una identificación total de la muestra.';return `<div class="detail-body"><div class="kicker">${r.id}</div><h3>${label(r.source_ref)} <span style="color:var(--muted)">→</span> ${label(r.target_ref)}</h3><span class="pill">${labels[r.relation_type]||r.relation_type}</span><dl><dt>Estado</dt><dd>${statuses[r.status]||r.status}</dd><dt>Confianza</dt><dd>${r.confidence||'no declarada'}</dd><dt>Matriz</dt><dd>${matrices[r.matrix_relevance]||r.matrix_relevance}</dd><dt>Evidencia</dt><dd>${r.evidence_role||'fuente documental'}</dd></dl><div class="note"><b>Redacción segura:</b><br>${safe}</div><p style="color:var(--muted);line-height:1.5">${r.notes||'Sin nota.'}</p>${r.testing_refs?.length?`<p><b>Vías de test:</b> ${r.testing_refs.map(x=>`<code>${x}</code>`).join(' · ')}</p>`:''}<h4>Fuentes clasificadas</h4><ul class="sources">${links(r)||'<li>Sin URL registrada</li>'}</ul></div>`}
function select(r){document.getElementById('detail').innerHTML=detail(r);document.getElementById('detail2').innerHTML=detail(r);document.querySelectorAll('.relation-card').forEach(x=>x.classList.toggle('selected',x.dataset.id===r.id))}
function renderStats(){const c=records.filter(x=>connected(x.id)).length;document.getElementById('stats').innerHTML=`<div class="stat"><b>${records.length}</b><small>entidades en el universo</small></div><div class="stat"><b>${relations.length}</b><small>relaciones candidatas</small></div><div class="stat"><b>${c}</b><small>entidades conectadas</small></div><div class="stat"><b>${records.length-c}</b><small>sin relación en esta tanda</small></div>`}
function renderGrid(){const rs=visibleRelations(),grid=document.getElementById('grid');let out='<div class="corner"></div>';records.forEach(x=>out+=`<div class="axis top" title="${x.display_name}">${x.display_name}</div>`);records.forEach(row=>{out+=`<div class="axis side" title="${row.display_name}">${row.display_name}</div>`;records.forEach(col=>{const r=rs.find(x=>x.source_kind==='entity'&&x.target_kind==='entity'&&x.source_ref===row.id&&x.target_ref===col.id);out+=r?`<div class="cell"><button class="dot-${r.relation_type}" data-id="${r.id}" title="${labels[r.relation_type]||r.relation_type}: ${row.display_name} → ${col.display_name}">${r.relation_type==='presumptive_presence_signal_for'?'P':''}</button></div>`:`<div class="cell empty">${entityVisible(row.id)&&entityVisible(col.id)?'·':''}</div>`})});grid.innerHTML=out;grid.querySelectorAll('button[data-id]').forEach(b=>b.onclick=()=>select(relations.find(r=>r.id===b.dataset.id)));document.getElementById('matrix-count').textContent=`${rs.length} relaciones visibles`}
function renderList(){const rs=visibleRelations(),list=document.getElementById('list');list.innerHTML=rs.length?rs.map(r=>`<button class="relation-card" data-id="${r.id}"><span class="row"><strong>${label(r.source_ref)} → ${label(r.target_ref)}</strong><span class="badge">${statuses[r.status]||r.status}</span></span><small>${labels[r.relation_type]||r.relation_type} · ${matrices[r.matrix_relevance]||r.matrix_relevance}</small></button>`).join(''):'<p class="empty">No hay relaciones con estos filtros.</p>';list.querySelectorAll('.relation-card').forEach(b=>b.onclick=()=>select(relations.find(r=>r.id===b.dataset.id)));document.getElementById('relation-count').textContent=`${rs.length} visibles de ${relations.length}`}
function render(){renderStats();renderGrid();renderList();document.getElementById('legend').innerHTML=data.graph.relation_types.map(x=>`<span><i class="dot-${x}"></i>${labels[x]||x}</span>`).join('');const used=new Set();relations.forEach(r=>{if(map.has(r.source_ref))used.add(r.source_ref);if(map.has(r.target_ref))used.add(r.target_ref)});document.getElementById('unconnected').innerHTML=records.filter(x=>!used.has(x.id)).map(x=>`<span title="${x.id}">${x.display_name}</span>`).join('')}
data.graph.relation_types.forEach(x=>document.getElementById('relation').insertAdjacentHTML('beforeend',`<option value="${x}">${labels[x]||x}</option>`));Object.entries(statuses).forEach(([x,y])=>document.getElementById('status').insertAdjacentHTML('beforeend',`<option value="${x}">${y}</option>`));Object.entries(matrices).forEach(([x,y])=>document.getElementById('matrix').insertAdjacentHTML('beforeend',`<option value="${x}">${y}</option>`));
document.getElementById('search').oninput=e=>{state.search=e.target.value.trim().toLowerCase();render()};document.getElementById('relation').onchange=e=>{state.relation=e.target.value;render()};document.getElementById('status').onchange=e=>{state.status=e.target.value;render()};document.getElementById('matrix').onchange=e=>{state.matrix=e.target.value;render()};document.getElementById('coverage').onchange=e=>{state.coverage=e.target.value;render()};document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));t.classList.add('active');document.getElementById('matrix-view').hidden=t.dataset.tab!=='matrix-view';document.getElementById('relations-view').hidden=t.dataset.tab!=='relations-view'});render();
</script></body></html>'''


def main() -> None:
    graph = json.loads(GRAPH.read_text(encoding="utf-8"))
    registry = json.loads(REGISTRY.read_text(encoding="utf-8"))
    sources = json.loads(SOURCES.read_text(encoding="utf-8"))
    public_graph = dict(graph)
    public_contract = dict(graph["evidence_contract"])
    public_contract.pop("prohibited_public_templates", None)
    public_graph["evidence_contract"] = public_contract
    payload = json.dumps({"graph": public_graph, "registry": registry, "sources": sources}, ensure_ascii=True, separators=(",", ":"))
    OUTPUT.write_text(HTML.replace("__DATA__", payload), encoding="utf-8")
    print(f"wrote={OUTPUT}")
    print(f"entities={len(registry['records'])}")
    print(f"relations={len(graph['relations'])}")


if __name__ == "__main__":
    main()
